create or replace function public.notify_self_appointment(p_appointment_id uuid,p_kind text,p_title text,p_body text,p_href text,p_dedupe_key text) returns uuid language plpgsql security definer set search_path = public as $$ declare v_id uuid; begin if auth.uid() is null or not exists (select 1 from public.appointments where id = p_appointment_id and patient_id = auth.uid()) then raise exception 'not_authorized'; end if; insert into public.notifications(user_id,kind,title,body,href,dedupe_key) values(auth.uid(),p_kind,p_title,p_body,p_href,p_dedupe_key) on conflict (dedupe_key) do update set title=excluded.title, body=excluded.body, href=excluded.href returning id into v_id; return v_id; end; $$;
revoke all on function public.notify_self_appointment(uuid,text,text,text,text,text) from public;
grant execute on function public.notify_self_appointment(uuid,text,text,text,text,text) to authenticated;
